        flexShrink: 0,
        borderBottom: '1px solid var(--mantine-color-gray-3)',
        display: 'flex',
        alignItems: 'center',
        paddingInline: 12,
        height: 44,
      }}
    >
      <Group gap={8} style={{ width: '100%' }}>
        {children}
      </Group>
    </Box>
  )
}

