    await setupWithTree()
    expect(textOf(screen.getByRole('button', { name: 'Set Drive folder for misc' }))).toContain('Not assigned')
    expect(screen.queryByRole('button', { name: 'Clear Drive folder for misc' })).toBeNull()
  })
})

