input.old_string:
// Effective Drive assignment for every file in the tree: its own override,
// else the nearest ancestor group's assignment. Mirrors the inheritance
// walk GroupNode/FileList do inline during render (same groupKey scheme:
// joined by '/', rooted at each top-level subgroup's own name), but usable
// outside a render tree — e.g. to build an upload job list.
//
// Throws if any file has no effective assignment: callers only call this
// once they intend to actually upload, at which point every file must
// resolve to a destination — the Upload All button stays disabled until
// then, so hitting this means that check was bypassed or is out of sync
// with this walk.
export function resolveEffectiveAssignments(
  tree: LocalFileGroup,
  { groupAssignments, fileOverrides }: Pick<DriveAssignmentsHandle, 'groupAssignments' | 'fileOverrides'>
): Map<string, DriveAssignment> {
  const result = new Map<string, DriveAssignment>()

  const walk = (group: LocalFileGroup, groupKey: string | null, inherited: DriveAssignment | null) => {
    const effective = (groupKey !== null ? groupAssignments.get(groupKey) : undefined) ?? inherited
    for (const file of group.files) {
      const assignment = fileOverrides.get(file.path) ?? effective
      if (!assignment) throw new Error(`No Drive folder assigned for "${file.path}"`)
      result.set(file.path, assignment)
    }
    for (const sub of group.subgroups) {
      walk(sub, groupKey !== null ? `${groupKey}/${sub.name}` : sub.name, effective)
    }
  }
  walk(tree, null, null)

  return result
}

